import org.slf4j.MDC
import reactor.core.publisher.Flux

class Service {
    fun processItems(items: List<String>): Flux<String> {
        MDC.setContextMap(mapOf("traceId" to "123")) // bad: MDC not propagated in Reactor
        return Flux.fromIterable(items).map { it.uppercase() }
    }
}

import org.slf4j.MDC
import reactor.core.publisher.Mono

class Service {
    fun processItem(item: String): Mono<String> {
        MDC.setContextMap(mapOf("traceId" to "123")) // bad: use Reactor context instead
        return Mono.just(item.uppercase())
    }
}

import org.slf4j.MDC
import reactor.util.context.Context

class Service {
    fun handle(ctx: Context) {
        MDC.setContextMap(emptyMap()) // bad: Context is available, use it
    }
}

import org.slf4j.MDC

class Service {
    fun handleRequest(traceId: String): String {
        MDC.setContextMap(mapOf("traceId" to traceId)) // ok: regular thread-based code
        return traceId
    }
}
